#include <iostream>

int main() {
    std::string questions[] = {
        "1. What year did C++ debut?",
        "2. Who invented C++?",
        "3. What is the predecessor of C++?"
    };

    std::string options[][4] = {
        {"A. 1985", "B. 1995", "C. 2000", "D. 1970"},
        {"A. Steve Jobs", "B. Bjarne Stroustrup", "C. Bill Gates", "D. Linus Torvalds"},
        {"A. Java", "B. Python", "C. C", "D. Basic"}
    };

    char answerKey[] = {'A', 'B', 'C'};
    int size = sizeof(questions) / sizeof(questions[0]);
    char guess;
    int score = 0;

    for (int i = 0; i < size; i++) {
        std::cout << "*******************************\n";
        std::cout << questions[i] << '\n';
        std::cout << "*******************************\n";

        // Print the options for this question
        for (int j = 0; j < 4; j++) {
            std::cout << options[i][j] << '\n';
        }

        std::cout << "Your answer (A/B/C/D): ";
        std::cin >> guess;
        guess = toupper(guess); // Force conversion to uppercase

        if (guess == answerKey[i]) {
            std::cout << "CORRECT!\n";
            score++;
        } else {
            std::cout << "WRONG! The correct answer was " << answerKey[i] << '\n';
        }
    }

    std::cout << "\nFINAL SCORE: " << score << "/" << size << "\n";
    return 0;
}

