#include <iostream>

// A recursive function to calculate factorials (e.g., 5! = 5 * 4 * 3 * 2 * 1)
int factorial(int n) {
    if (n <= 1) {
        return 1; // Base Case: Stops the recursion chain!
    }
    // Recursive Case: Calls itself with a smaller number
    return n * factorial(n - 1);
}

int main() {
    std::cout << factorial(5) << '\n'; // Prints: 120
    return 0;
}

