#include <iostream>

class Stove {
private: // Data hidden safely from unsafe outside tampering
    int temperature = 0;

public:
    // Getter method
    int getTemperature() {
        return temperature;
    }

    // Setter method containing structural validation safeguards
    void setTemperature(int newTemp) {
        if (newTemp < 0 || newTemp > 500) {
            std::cout << "Error! Temperature out of safe structural bounds!\n";
        } else {
            temperature = newTemp; // Valid parameter saved securely
        }
    }
};

int main() {
    Stove oven;
    oven.setTemperature(350);
    std::cout << "Oven heat is: " << oven.getTemperature() << " degrees.\n";
    return 0;
}

#include <iostream>

// Parent Class
class Shape {
public:
    double area;
    double volume;
};

// Child Class inherits from Shape using public modifier notation
class Cube : public Shape {
public:
    double side;

    Cube(double s) {
        side = s;
        // We can access 'area' and 'volume' because we inherited them!
        area = 6 * (side * side);
        volume = side * side * side;
    }
};

class Sphere : public Shape {
public:
    double radius;

    Sphere(double r) {
        radius = r;
        area = 4 * 3.14159 * (radius * radius);
        volume = (4.0 / 3.0) * 3.14159 * (radius * radius * radius);
    }
};

int main() {
    Cube myCube(10);
    Sphere mySphere(5);

    std::cout << "Cube Area: " << myCube.area << " cm^2\n";
    std::cout << "Sphere Volume: " << mySphere.volume << " cm^3\n";
    return 0;
}
